/* From Uiverse.io by StefanR1901 - Tags: form, input, discount form */
.__UIV_SCOPE__ .colorful-form {
  max-width: 400px;
  margin: 0 auto;
  padding: 20px;
  background-color: #f5f5f5;
  border-radius: 10px;
}

.__UIV_SCOPE__ .form-group {
  margin-bottom: 20px;
}

.__UIV_SCOPE__ .form-label {
  display: block;
  font-weight: bold;
  margin-bottom: 5px;
  color: #333;
}

.__UIV_SCOPE__ .form-input {
  width: 100%;
  padding: 10px;
  border: none;
  background-color: #fff;
  color: #333;
  border-radius: 5px;
}

.__UIV_SCOPE__ textarea.form-input {
  height: 100px;
}

.__UIV_SCOPE__ .form-button {
  display: block;
  width: 100%;
  padding: 10px;
  background-color: #ff6f69;
  color: #fff;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

.__UIV_SCOPE__ .form-button:hover {
  background-color: #ff5f59;
}
